package devin

import (
	"os"
	"testing"
	"time"

	"github.com/Wei-Shaw/sub2api/internal/pkg/devin/pb"
	"github.com/stretchr/testify/require"
	"google.golang.org/protobuf/proto"
)

func TestAccountPricingWireFixture(t *testing.T) {
	// Generated by protoc 33.0 from the independent upstream subset, not pb.
	// From testdata/model_pricing, regenerate using:
	// protoc -I . --encode=exa.codeium_common_pb.GetCliModelConfigsResponse upstream_pricing.proto < models.textproto > models.bin
	wire, err := os.ReadFile("testdata/model_pricing/models.bin")
	require.NoError(t, err)
	var catalog pb.GetCliModelConfigsResponse
	require.NoError(t, proto.Unmarshal(wire, &catalog))
	m := FindModel(catalog.ClientModelConfigs, "future-promoted-v99")
	require.NotNil(t, m)
	require.Equal(t, pb.ModelPricingType_MODEL_PRICING_TYPE_API, m.PricingType)
	require.Equal(t, pb.ModelCostTier_MODEL_COST_TIER_FREE, m.ModelCostTier)
	require.True(t, m.GetPromoStatus().GetIsActive())
	require.EqualValues(t, 4102444800, m.GetPromoStatus().GetEndDate().Seconds)
	now := time.Date(2026, 10, 28, 0, 0, 0, 0, time.UTC)
	until := now.Add(2 * time.Minute)
	end, free := ModelFreeUntil(m, now, until)
	require.True(t, free)
	require.Equal(t, until, end, "undated free evidence is still bounded by catalog freshness")
}
